<?php
declare(strict_types=1);
use SwapFix\Support\Assets;
$photo = $item['image'] !== null ? Assets::image($item['image']) : null;
$detailsUrl = $catalogUrl(['item'=>$item['id']]);
$isRepair = $item['type'] === 'repair';
$isTrade = $item['type'] === 'exchange';
?>
<article class="product-card reveal">
    <div class="product-photo <?= $isRepair ? 'service-photo' : '' ?>"><a href="<?= $escape($detailsUrl) ?>" data-open-dialog="detail-<?= $escape($item['id']) ?>" aria-label="View <?= $escape($item['name']) ?> details"><?php if ($photo): ?><img src="<?= $escape($photo['src']) ?>" srcset="<?= $escape($photo['srcset']) ?>" sizes="(max-width: 520px) 90vw, (max-width: 1024px) 45vw, 280px" width="<?= $photo['width'] ?>" height="<?= $photo['height'] ?>" alt="<?= $escape($item['alt']) ?>" loading="lazy" decoding="async"><?php else: ?><span class="service-symbol"><?= $icon($item['icon']) ?></span><?php endif ?></a><span class="listing-badge <?= $isRepair || $isTrade ? 'teal' : '' ?>"><?= $icon($isRepair ? 'wrench' : ($isTrade ? 'swap' : 'bag')) ?><?= $escape($item['badge']) ?></span><button class="save-button icon-button" type="button" data-save="<?= $escape($item['id']) ?>" data-save-name="<?= $escape($item['name']) ?>" aria-label="Save <?= $escape($item['name']) ?>" aria-pressed="false" hidden><?= $icon('heart') ?></button></div>
    <div class="product-body"><p class="item-condition"><?= $icon('check-circle') ?><?= $escape($item['condition']) ?></p><h3><a href="<?= $escape($detailsUrl) ?>" data-open-dialog="detail-<?= $escape($item['id']) ?>"><?= $escape($item['name']) ?></a></h3><p class="product-specification"><?= $escape($item['specification']) ?></p><div class="product-price"><?php if ($isRepair): ?><small>From</small><?php endif ?><?= $isTrade ? '<span class="trade-price">Open to offers</span>' : '&#8369;' . number_format($item['price']) ?><a href="<?= $escape($detailsUrl) ?>" data-open-dialog="detail-<?= $escape($item['id']) ?>" class="card-arrow" aria-label="View <?= $escape($item['name']) ?>"><?= $icon('arrow-up-right') ?></a></div><p class="item-location"><?= $icon($isRepair ? 'message' : 'pin') ?><?= $escape($item['location']) ?></p></div>
</article>
<dialog class="detail-dialog" id="detail-<?= $escape($item['id']) ?>" aria-labelledby="title-<?= $escape($item['id']) ?>" <?= $openItem === $item['id'] ? 'open' : '' ?>><a class="icon-button dialog-close" href="<?= $escape($catalogUrl()) ?>" data-close-dialog aria-label="Close <?= $escape($item['name']) ?> details"><?= $icon('close') ?></a><?php if ($photo): ?><img class="detail-photo" src="<?= $escape($photo['src']) ?>" width="<?= $photo['width'] ?>" height="<?= $photo['height'] ?>" alt="<?= $escape($item['alt']) ?>" loading="lazy" decoding="async"><?php else: ?><div class="detail-service"><?= $icon($item['icon']) ?></div><?php endif ?><div class="detail-body"><p class="eyebrow">SAMPLE <?= $isRepair ? 'SERVICE' : ($isTrade ? 'EXCHANGE' : 'LISTING') ?></p><h2 id="title-<?= $escape($item['id']) ?>"><?= $escape($item['name']) ?></h2><p><?= $escape($item['specification']) ?></p><strong class="detail-price"><?= $isTrade ? 'Open to offers' : ($isRepair ? 'Estimate from ' : '') . '&#8369;' . number_format($item['price']) ?></strong><p><?= $escape($item['description']) ?></p><dl><div><dt><?= $isRepair ? 'Approval' : 'Condition' ?></dt><dd><?= $escape($item['condition']) ?></dd></div><div><dt><?= $isRepair ? 'Service details' : 'Known defects' ?></dt><dd><?= $escape($item['defects']) ?></dd></div></dl><button class="button button-primary detail-save" type="button" data-save="<?= $escape($item['id']) ?>" data-save-name="<?= $escape($item['name']) ?>" aria-pressed="false" hidden><?= $icon('heart') ?><span data-save-label>Save for later</span></button><p class="small-note">Design preview. Saving keeps this sample on this browser only.</p></div></dialog>
